#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_add() {
        assert_eq!(add(2, 3), 5);
        assert_eq!(add(-1, 1), 0);
        assert_eq!(add(0, 0), 0);
    }

    #[test]
    fn test_subtract() {
        assert_eq!(subtract(10, 4), 6);
        assert_eq!(subtract(0, 5), -5);
    }

    #[test]
    fn test_percent_of() {
        assert!((percent_of(25, 200) - 12.5).abs() < 1e-9);
        assert!((percent_of(1, 4) - 25.0).abs() < 1e-9);
        assert_eq!(percent_of(10, 0), 0.0);
